from __future__ import annotations

import base64
import gzip
import hashlib
import json
import os
import shutil
import subprocess
import sys
import traceback
from datetime import datetime
from pathlib import Path

PROJECT = Path(os.environ.get("PHOCAP_PROJECT", r"C:\PhoCap")).resolve()
APP = PROJECT / "app"

EXPECTED_HASHES = {'app/routers/users.py': '7663bd710c5986ddf8ceb17f684587d5c57c0a96b228cf85f44321c8048ee4ca', 'app/templates/users/list.html': 'b2f4acea09af8f84dd08d9cd00aee855e33e6996e763d3eba6dca30575bdd1ee'}
PAYLOAD = {'app/routers/users.py': '', 'app/templates/users/list.html': '', 'app/templates/users/bulk_level_all_preview.html': ''}

STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP = PROJECT / "exports" / f"backup_bai_13b_6_v1_5_cap_tat_ca_tai_khoan_{STAMP}"
MANIFEST = BACKUP / "manifest.json"


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def preflight() -> None:
    print("Kiểm tra đúng trạng thái sau bản MENU CHÍNH XÁC...")
    errors = []

    for rel, expected in EXPECTED_HASHES.items():
        path = PROJECT / rel
        if not path.exists():
            errors.append(f"THIẾU: {rel}")
            continue

        actual = sha256(path)
        if actual != expected:
            errors.append(
                f"KHÁC SOURCE DỰ KIẾN: {rel}\n"
                f"  expected={expected}\n"
                f"  actual  ={actual}"
            )

    if errors:
        print("")
        print("DỪNG AN TOÀN - KHÔNG CÓ TỆP NÀO BỊ THAY ĐỔI.")
        for item in errors:
            print(" -", item)
        print("")
        print("Hãy gửi ảnh Terminal này để kiểm tra source hiện tại.")
        raise RuntimeError("Preflight không đạt.")


def backup_files() -> list[dict]:
    BACKUP.mkdir(parents=True, exist_ok=False)
    manifest = []

    for rel in PAYLOAD:
        src = PROJECT / rel
        existed = src.exists()
        manifest.append({"path": rel, "existed": existed})

        if existed:
            dst = BACKUP / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    MANIFEST.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return manifest


def restore_files(manifest: list[dict]) -> None:
    for item in reversed(manifest):
        target = PROJECT / item["path"]
        if item["existed"]:
            src = BACKUP / item["path"]
            if src.exists():
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src, target)
        elif target.exists() and target.is_file():
            target.unlink()


def write_files() -> None:
    for rel, encoded in PAYLOAD.items():
        target = PROJECT / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(
            gzip.decompress(base64.b64decode(encoded))
        )


def verify() -> None:
    users_py = APP / "routers" / "users.py"

    subprocess.run(
        [sys.executable, "-m", "py_compile", str(users_py)],
        cwd=PROJECT,
        check=True,
    )

    from jinja2 import Environment, FileSystemLoader
    env = Environment(loader=FileSystemLoader(str(APP / "templates")))
    env.get_template("users/list.html")
    env.get_template("users/bulk_level_all_preview.html")

    users_text = users_py.read_text(encoding="utf-8-sig")
    list_text = (APP / "templates" / "users" / "list.html").read_text(
        encoding="utf-8-sig"
    )

    required_users = [
        "BAI_13B_6_V1_5_CAP_TAT_CA_TAI_KHOAN_THEO_CAP",
        '@router.get("/cap-tat-ca-theo-cap"',
        '@router.post("/cap-tat-ca-theo-cap"',
        "school_level=school_level",
    ]
    for marker in required_users:
        if marker not in users_text:
            raise RuntimeError(f"Kiểm tra users.py không đạt: {marker}")

    required_template = [
        "CẤP TÀI KHOẢN TOÀN CẤP",
        "Tạo tài khoản cho tất cả",
        "/tai-khoan/cap-tat-ca-theo-cap?cap={ cap_hoc }",
    ]
    for marker in required_template:
        if marker not in list_text:
            raise RuntimeError(f"Kiểm tra users/list.html không đạt: {marker}")


def clear_cache() -> None:
    for cache in APP.rglob("__pycache__"):
        if cache.is_dir():
            shutil.rmtree(cache, ignore_errors=True)


def main() -> int:
    print("=" * 98)
    print("BÀI 13B-6 V1.5 - TẠO TÀI KHOẢN CHO TẤT CẢ TRƯỜNG THEO TỪNG CẤP")
    print("=" * 98)
    print("")
    print("ÁP DỤNG CHO:")
    print(" - TK trường Mầm non")
    print(" - TK trường Tiểu học")
    print(" - TK trường THCS")
    print("")
    print("CƠ CHẾ AN TOÀN:")
    print(" - Chỉ cấp cho trường thuộc đúng cấp đang mở.")
    print(" - Trường đã có tài khoản được giữ nguyên.")
    print(" - Không đổi mật khẩu tài khoản đã có.")
    print(" - Không tạo trùng.")
    print(" - Có màn hình xem trước và xác nhận trước khi chạy hàng loạt.")
    print(" - Sau khi hoàn thành có thể tải Excel bàn giao tài khoản/mật khẩu tạm.")
    print("")

    preflight()
    manifest = backup_files()

    try:
        write_files()
        verify()
        clear_cache()

        print("")
        print("CAI DAT BAI 13B-6 V1.5 CAP TAT CA TAI KHOAN THANH CONG")
        print("Backup:", BACKUP)
        return 0

    except Exception:
        traceback.print_exc()
        print("")
        print("CÓ LỖI - ĐANG KHÔI PHỤC TỰ ĐỘNG...")
        restore_files(manifest)
        print("ĐÃ KHÔI PHỤC VỀ TRƯỚC BÀI 13B-6 V1.5.")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
